import {ITEMS} from './data-v14.js';
import {CH3_GEAR} from './chapter3-runtime-v14.js';
import {POTIONS,QUALITIES,TRIAL_FLOORS} from './systems-data-v14.js';
import {routeHint} from './navigation-v14.js';
import {paintedFX} from './combat-visuals-v14.js';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function journalHTML(g,view){const history=view==='history',entries=g.journalEntries(history);return `<nav class="bag-categories"><button data-journal="current" class="${!history?'on':''}">当前</button><button data-journal="history" class="${history?'on':''}">历史</button></nav><p class="muted">！可以接取　<span class="silver">？待完成</span>　<span class="gold">？下一位联系人 / 可交付</span></p>${entries.map(q=>{const goal=g.questGoal(q.id),active=q.status==='active';return `<article class="quest-row"><div class="quest-title"><h3>${esc(q.type)} · ${esc(q.name)}</h3><span class="${active&&g.ready(q.id)?'gold':''}">${q.status==='done'?'已完成':q.status==='expired'?'已搁置 · 离开该区域':g.ready(q.id)?'可以交付':'进行中'}</span></div><p>${esc(q.desc)}</p>${active?`<p class="route-hint">${esc(goal?.text||'')} · ${esc(routeHint(g,goal))}</p><button data-track="${q.id}">追踪这项任务</button>`:''}</article>`;}).join('')||'<p class="detail-empty">这里暂时没有任务记录。</p>'}<p class="tip">离开章节区域后，未办完的支线保存在历史中。进出房间不会中断差事。</p><button class="ghost" data-track="main">追踪主线</button>`;}
const shell=(title,body)=>`<div class="modal"><section class="panel hell-panel"><header class="panel-head"><h2>${title}</h2><button data-act="resume">返回 ×</button></header><div class="panel-body">${body}</div></section></div>`;
export function shopHTML(g,{miniItemIcon}){return shell('旅途药箱',`<div class="summary"><span>金币 <b>${g.p.gold}</b></span><span>疗伤、回蓝分别冷却7秒</span></div><div class="teaching-grid">${g.potionStock().map(id=>{const v=POTIONS[id];return `<article class="teaching-card">${miniItemIcon(id)}<h3>${v.name}</h3><p>${v.desc}</p><small>携带 ${g.p.items[id]||0} 瓶</small><br><button data-buy-potion="${id}" ${g.p.gold<v.cost?'disabled':''}>购买 · ${v.cost} 金</button></article>`;}).join('')}</div><p class="tip">小、中、大、特制药水随旅程逐步出售。换页与换药不会重置冷却。</p>`);}
export function trialHTML(g){const t=g.v13?.trial||{cleared:0,claims:{},active:0};return shell('回声裂隙 · 五重试炼',`${g.ch3?.trialReward?.length?`<article class="trial-floor"><div><h3>上次试炼留下的战利品</h3><p>这份旧记录的奖励仍为你保留，选一件收好。</p>${g.ch3.trialReward.map((r,i)=>`<button data-hell="trialReward" data-hell-arg="${i}">${esc(CH3_GEAR[r.id]?.name||ITEMS[r.id]?.name||'领取补给')}</button>`).join('')}</div></article>`:''}<p>每层只面对一位守井残影。依次击败后，下一层开启；层间可以离开补给，进度保留。</p><p class="tip">击败时装备直接收进行囊，满包会保留待领。首次奖励只发一次；重复挑战仍有材料和装备机会。</p>${t.active?`<p class="gold">正在挑战第 ${t.active} 层</p><button data-hell="trialExit">退出本层 · 保留已通关进度</button>`:''}<div class="trial-floors">${TRIAL_FLOORS.map((f,i)=>`<article class="trial-floor ${t.cleared>i?'cleared':''}"><span class="floor-number">${i+1}</span><div><h3>${f.name}</h3><p>建议 Lv.${f.level} · 生命 ${f.hp} · 普攻 ${f.damage} 原始伤害</p><p class="quality-${f.quality}">首通：${QUALITIES[f.quality].name}装备 · ${f.xp}经验 · ${f.gold}金${i===4?' · 通用被动「百折不熄」':''}</p><button data-hell="trial" data-hell-arg="${f.id}" ${t.active||i>t.cleared||!g.flags.ch3HeroRecovered?'disabled':''}>${t.cleared>i?'再次挑战':i>t.cleared?'先通过上一层':'进入本层'}</button></div></article>`).join('')}</div>${t.cleared===5?'<p class="gold">五重残响已经走过。被动「百折不熄」已收入技能页。</p>':''}`);}
export function drawManaMotes(c,bank,g){for(const m of g.manaMotes||[]){const alpha=Math.min(1,m.life/2),pulse=1+Math.sin(g.time*4+m.x)*.08;c.save();c.globalAlpha=alpha;paintedFX(c,bank,'spirit',Math.floor(g.time*7)%4,m.x,m.y+7,25*pulse,31*pulse,0,.8);c.fillStyle='#c6f7ff';c.beginPath();c.ellipse(m.x,m.y-5,2.5,4,0,0,7);c.fill();c.restore();}}
